package com.smartmart.intelligence.controller;
import com.smartmart.intelligence.dto.*; import com.smartmart.intelligence.service.InventoryIntelligenceService; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/intelligence") @RequiredArgsConstructor @PreAuthorize("hasRole('MANAGER')") public class IntelligenceController { private final InventoryIntelligenceService service; @GetMapping("/stock-out-risks") public List<StockInsightResponse> risks(){return service.stockOutRisks();} @GetMapping("/reorder-recommendations") public List<StockInsightResponse> reorder(){return service.reorderRecommendations();} @GetMapping("/expiry") public List<ExpiryInsightResponse> expiry(){return service.expiryInsights();} }
